    parts = version.split('.')
    if len(parts) != 3:
        raise ValueError("Version string must have exactly three dot-separated parts (MAJOR.MINOR.PATCH).")

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        raise ValueError("Each part of the version string must be a non-negative integer.")

    if not all(str(p) == parts[i] and p >= 0 for i, p in enumerate([major, minor, patch])):
        raise ValueError("Each part of the version string must be a non-negative integer and contain only digits.")

    return major, minor, patch
