def balanced_brackets(s: str) -> bool:
    """
    Checks if the round, square and curly brackets in the string `s` are balanced and correctly nested.
    Ignores every character that is not one of ( ) [ ] { }.
    An empty string returns True.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    open_brackets = set(bracket_map.values())
    close_brackets = set(bracket_map.keys())

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top_of_stack = stack.pop()
            if top_of_stack != bracket_map[char]:
                return False

    return not stack
```

