def balanced_brackets(s: str) -> bool:
    """
    Checks if the round, square and curly brackets in the string `s` are balanced and correctly nested.
    Ignores every character that is not one of ( ) [ ] { }.

    Args:
        s: The input string.

    Returns:
        True if the brackets are balanced and correctly nested, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    open_brackets = {'(', '[', '{'}

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return not stack

