def parse_semver(version):
    parts = version.split('.')
    if len(parts) != 3:
        raise ValueError("Version string must have exactly three parts (MAJOR.MINOR.PATCH).")

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        raise ValueError("Version parts must be non-negative integers.")

    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Version parts must be non-negative integers.")

    return (major, minor, patch)
